INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Zwei-Faktor-Authentifizierung nur für sensible Systeme nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Breiter Schutz sinnvoll"}, {"text": "Ja", "correct": false, "because": "Allgemeine Sicherheit erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit 2FA?', 3, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Zusätzliche Ebene schützt"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren gehören zu 2FA?', 5, '[{"text": "Wissen (Passwort)", "correct": true, "because": "Etwas, das man weiß"}, {"text": "Besitz (SMS)", "correct": true, "because": "Etwas, das man hat"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2FA kombiniert zwei Methoden. b) Es schützt nur vor Passwortdiebstahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz auch vor anderen Angriffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der 2FA-Umsetzung?', 4, '[{"text": "Zweiter Faktor", "correct": false, "because": "Kern der Methode"}, {"text": "Nutzeridentität", "correct": false, "because": "Basis der Authentifizierung"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2FA auch biometrische Daten nutzen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Fingerabdruck als Faktor"}, {"text": "Nein", "correct": false, "because": "Vielfältige Faktoren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel ist typisch für 2FA?', 3, '[{"text": "SMS-Code", "correct": true, "because": "Häufig als zweiter Faktor"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kombinationen sind bei 2FA üblich?', 5, '[{"text": "Passwort + App", "correct": true, "because": "Wissen und Besitz"}, {"text": "Passwort + Fingerabdruck", "correct": true, "because": "Wissen und Inhärenz"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Kein Faktor"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2FA erhöht die Sicherheit. b) Es ist immer unbequem. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bequemlichkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für 2FA?', 4, '[{"text": "Passwort", "correct": false, "because": "Erster Faktor"}, {"text": "Zweiter Faktor", "correct": false, "because": "Zweite Ebene"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2FA nur mit SMS möglich?', 2, '[{"text": "No", "correct": true, "because": "Apps, Token etc. nutzbar"}, {"text": "Ja", "correct": false, "because": "Vielfältige Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren verbessern 2FA?', 4, '[{"text": "Hardware-Token", "correct": true, "because": "Physischer Besitz"}, {"text": "Biometrie", "correct": true, "because": "Individuelle Merkmale"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2FA alle Angriffe verhindert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Reduziert, aber nicht 100%"}, {"text": "Ja", "correct": false, "because": "Begrenzte Wirksamkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei 2FA?', 3, '[{"text": "Sicherer zweiter Faktor", "correct": true, "because": "Schlüssel zur Sicherheit"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Sekundär"}, {"text": "Grafische Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2FA nutzt zwei verschiedene Faktoren. b) Es ist nur für Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Nutzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden sind für 2FA üblich?', 5, '[{"text": "TOTP (App-Codes)", "correct": true, "because": "Zeitbasierte Codes"}, {"text": "SMS", "correct": true, "because": "Weit verbreitet"}, {"text": "Maximale Speicherung", "correct": false, "because": "Kein Faktor"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei 2FA unwichtig?', 3, '[{"text": "Faktorvielfalt", "correct": false, "because": "Erhöht Sicherheit"}, {"text": "Nutzeridentität", "correct": false, "because": "Kern der Methode"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt 2FA auch vor Phishing?', 3, '[{"text": "Ja", "correct": true, "because": "Schwieriger zu umgehen"}, {"text": "Nein", "correct": false, "because": "Erhöht Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2FA immer einen zweiten Faktor braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Definition von 2FA"}, {"text": "Nein", "correct": false, "because": "Zwei Faktoren nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wähle ich für sichere 2FA?', 4, '[{"text": "Authenticator-App", "correct": true, "because": "Sicherer als SMS"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
